/**
 * Render an invoice as plain text.
 * @param {{ number?: string, customerId: string, issueDate: string, status: string, lines: Array<{ qty: number, name: string, unitPrice: number, discountPercent?: number }> }} invoice
 * @returns {string}
 */
export function renderInvoiceText(invoice) {
  const lines = [];

  lines.push(invoice.number ?? 'DRAFT');

  const customerResult = getCustomer(invoice.customerId);
  const customerName = customerResult.ok ? customerResult.value.name : invoice.customerId;
  lines.push(customerName);

  for (const line of invoice.lines) {
    const total = lineTotal(line);
    const discount = lineDiscount(line);
    let lineText = `${line.qty} × ${line.name} @ ${formatEuros(line.unitPrice)} = ${formatEuros(total)}`;
    if (discount > 0) {
      lineText += ` (${line.discountPercent}% off: -${formatEuros(discount)})`;
    }
    lines.push(lineText);
  }

  const totals = invoiceTotals(invoice);
  if (totals.discount > 0) {
    lines.push(`Subtotal: ${formatEuros(totals.subtotal)}`);
    lines.push(`Discount: -${formatEuros(totals.discount)}`);
  }
  lines.push(`Total: ${formatEuros(totals.total)}`);

  return lines.join('\n');
}

