test('renderInvoiceText VAT appears above Total line', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });
  assert.equal(r.ok, true);

  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');
  let vatIndex = -1;
  let totalIndex = -1;
  for (let i = 0; i < lines.length; i++) {
    if (lines[i].startsWith('VAT:')) vatIndex = i;
    if (lines[i].startsWith('Total:')) totalIndex = i;
  }
  assert.ok(vatIndex >= 0);
  assert.ok(totalIndex > vatIndex);
});

