test('invoiceTotals VAT formula is correct', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 5000, discountPercent: 10, vatRate: 21 },
      { qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 9 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const subtotal = 2 * 5000 + 1 * 10000;
  const discount = Math.round(2 * 5000 * 0.1) + Math.round(1 * 10000 * 0);
  const vat = Math.round((2 * 5000 - Math.round(2 * 5000 * 0.1)) * 0.21) + Math.round((1 * 10000) * 0.09);
  const expectedTotal = subtotal - discount + vat;
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, discount);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, expectedTotal);
});

